    "\n"
    "<script>\n"
    "(function(){\n"
    " var MEDIA='https://media.audreaming.com/product/v2/';\n"
    " var reduce=window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches;\n"
    " /* Media from R2. Offline boards (SoftAP) simply hide what cannot load. */\n"
    " document.querySelectorAll('img[data-media]').forEach(function(img){\n"
    "  var box=img.closest('.arch,figure');\n"
    "  img.onerror=function(){if(box)box.classList.add('nomedia');};\n"
    "  img.src=MEDIA+img.dataset.media;\n"
    " });\n"
    " var video=document.getElementById('heroVideo'),hero=document.getElementById('heroMedia');\n"
    " video.poster=MEDIA+'hero-poster.webp';\n"
    " ['webm','mp4'].forEach(function(t){var s=document.createElement('source');s.src=MEDIA+'hero.'+t;s.type='video/'+t;video.appendChild(s);});\n"
    " video.addEventListener('error',function(){hero.classList.add('nomedia');},true);\n"
    " var probe=new Image();probe.onerror=function(){hero.classList.add('nomedia');};probe.src=video.poster;\n"
    " if(!reduce){video.autoplay=true;video.play&&video.play().catch(function(){});}\n"
    " /* Exploded view: scroll position drives --p; the pointer tilts the model. */\n"
    " var section=document.getElementById('inside'),device=document.getElementById('device'),parts=document.querySelectorAll('#parts li');\n"
    " function explode(){\n"
    "  if(innerWidth<=960){device.style.setProperty('--p',.85);parts.forEach(function(li){li.classList.add('on');});return;}\n"
    "  var r=section.getBoundingClientRect(),span=r.height-innerHeight,t=Math.min(1,Math.max(0,-r.top/(span||1)));\n"
    "  var p=t<.1?0:Math.min(1,(t-.1)/.6);p=p*p*(3-2*p);\n"
    "  device.style.setProperty('--p',p.toFixed(3));\n"
    "  parts.forEach(function(li){li.classList.toggle('on',t>=parseFloat(li.dataset.at));});\n"
    " }\n"
    " addEventListener('scroll',explode,{passive:true});addEventListener('resize',explode);explode();\n"
    " section.addEventListener('pointermove',function(e){if(reduce)return;var x=e.clientX/innerWidth-.5;device.style.setProperty('--rz',(-38+x*24).toFixed(1)+'deg');});\n"
    " /* QR pattern for the setup demo (decorative). */\n"
    " function qr(el){\n"
    "  var seed=7;function rnd(){seed=(seed*16807)%2147483647;return seed/2147483647;}\n"
    "  for(var y=0;y<21;y++)for(var x=0;x<21;x++){\n"
    "   var c=document.createElement('i'),f=function(a,b){return x>=a&&x<a+7&&y>=b&&y<b+7;},dark;\n"
    "   if(f(0,0)||f(14,0)||f(0,14)){var fx=x>=14?x-14:x,fy=y>=14?y-14:y;dark=fx==0||fx==6||fy==0||fy==6||(fx>=2&&fx<=4&&fy>=2&&fy<=4);}\n"
    "   else dark=rnd()<.45;\n"
    "   if(!dark)c.className='o';el.appendChild(c);\n"
    "  }\n"
    " }\n"
    " document.querySelectorAll('[data-qr]').forEach(qr);\n"
    " /* Setup steps: auto-advance, pause on interaction. */\n"
    " var demo=document.getElementById('demo'),buttons=document.querySelectorAll('#steps button'),bar=document.getElementById('stepProgress');\n"
    " var step=1,timer=null,start=0,DURATION=5200,paused=false;\n"
    " function go(n){step=n;demo.dataset.step=String(n);buttons.forEach(function(b){b.setAttribute('aria-current',b.dataset.go==n?'step':'false');});\n"
    "  demo.querySelectorAll('.view').forEach(function(v){v.style.animation='none';v.offsetHeight;v.style.animation='';});start=performance.now();}\n"
    " function tick(now){if(!paused&&!reduce){var t=(now-start)/DURATION;bar.style.width=Math.min(100,t*100)+'%';if(t>=1)go(step%3+1);}requestAnimationFrame(tick);}\n"
    " buttons.forEach(function(b){b.addEventListener('click',function(){go(+b.dataset.go);paused=true;bar.style.width='100%';clearTimeout(timer);timer=setTimeout(function(){paused=false;start=performance.now();},9000);});});\n"
    " go(1);requestAnimationFrame(tick);\n"
    " /* Reveal on scroll. */\n"
    " if('IntersectionObserver' in window){var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});},{rootMargin:'0px 0px -8% 0px'});document.querySelectorAll('.reveal').forEach(function(e){io.observe(e);});}\n"
    " else document.querySelectorAll('.reveal').forEach(function(e){e.classList.add('in');});\n"
    " /* Local network only: admin, Wi-Fi setup and AI entry points (the domain never exposes them). */\n"
    " fetch('/api/system',{cache:'no-store'}).then(function(r){if(!r.ok)throw 0;return r.json();}).then(function(d){\n"
    "  document.querySelectorAll('.local-only').forEach(function(e){e.hidden=false;});\n"
    "  var info=document.getElementById('boardInfo');if(d&&d.ip)info.textContent='이 보드: '+(d.product||'').toUpperCase()+' · '+d.ip+(d.mdns_url?' · '+d.mdns_url.replace(/^https?:\\/\\//,'').replace(/\\/$/,''):'');\n"
    " }).catch(function(){document.getElementById('startText').textContent='지금 보이는 화면은 제품의 기본 페이지입니다. 보드와 같은 Wi-Fi에서 접속하면 관리자 페이지로 원하는 웹 파일을 올릴 수 있습니다.';});\n"
    "})();\n"
    "</script>\n"
    "</body>\n"
    "</html>\n";
const size_t FACTORY_INDEX_HTML_LEN = sizeof(FACTORY_INDEX_HTML) - 1;
